<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?= auth_escape(auth_csrf_token()) ?>"><title>Messages · Paw Net</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet"><style>
:root{--purple:#7056df;--ink:#28263b;--muted:#85849a;--line:#eceaf2;--bg:#f8f7fb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px 'DM Sans',Arial,sans-serif}.shell{max-width:1200px;margin:0 auto;padding:28px 24px}.top{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px}.top a{color:var(--purple);font-size:12px;text-decoration:none;font-weight:700}.top h1{font:700 27px 'Playfair Display';margin:0}.top p{color:var(--muted);font-size:12px;margin:5px 0 0}.inbox{height:min(690px,calc(100vh - 150px));min-height:440px;display:grid;grid-template-columns:320px 1fr;gap:14px}.panel{background:white;border:1px solid var(--line);border-radius:15px;overflow:hidden}.threads{padding:16px}.threads h2{font-size:14px;margin:0 0 14px}.thread{display:flex;gap:10px;align-items:center;width:100%;padding:11px;border:0;border-radius:11px;background:white;text-align:left;cursor:pointer}.thread:hover,.thread.active{background:#f3f0ff}.avatar{width:38px;height:38px;flex:0 0 auto;display:grid;place-items:center;border-radius:50%;background:#eeeaff;color:var(--purple);font-weight:800}.thread b,.thread small{display:block}.thread b{font-size:12px}.thread small{color:var(--muted);font-size:10px;margin-top:4px;max-width:200px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.chat{display:flex;flex-direction:column}.chat-head{height:70px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:11px;padding:0 18px}.chat-head b,.chat-head small{display:block}.chat-head b{font-size:13px}.chat-head small{font-size:10px;color:var(--muted);margin-top:4px}.log{flex:1;overflow:auto;padding:20px;display:flex;flex-direction:column;gap:10px}.bubble{max-width:min(76%,510px);padding:11px 13px;border-radius:13px;background:#f2f0f7;font-size:12px;line-height:1.5;align-self:flex-start;overflow-wrap:anywhere}.bubble.mine{background:#7056df;color:#fff;align-self:flex-end}.bubble small{display:block;margin-top:5px;font-size:9px;opacity:.7}.empty{margin:auto;text-align:center;padding:25px;color:var(--muted);font-size:12px}.send{display:flex;gap:9px;border-top:1px solid var(--line);padding:13px}.send input{flex:1;min-width:0;padding:12px;border:1px solid var(--line);border-radius:10px;font:12px 'DM Sans';outline-color:#c9bdff}.send button{border:0;border-radius:10px;padding:0 18px;background:var(--purple);color:white;font-weight:800;cursor:pointer}.send button:disabled{opacity:.55}.status{margin:0 18px 0 auto;color:var(--muted);font-size:10px}.mobile-back{display:none}@media(max-width:700px){.shell{padding:18px 12px}.inbox{height:calc(100vh - 120px);min-height:0;display:block;position:relative}.threads{height:100%;overflow:auto}.chat{display:none;position:absolute;inset:0}.inbox.chat-open .threads{display:none}.inbox.chat-open .chat{display:flex}.mobile-back{display:inline;border:0;background:none;color:var(--purple);font-weight:800;font-size:17px}.top h1{font-size:23px}}
</style></head><body><main class="shell"><header class="top"><div><h1>Messages</h1><p>Chat with people interested in your pets, <?= auth_escape($name) ?>.</p></div><a href="seller.php">← Seller dashboard</a></header><div id="inbox" class="inbox"><section class="panel threads"><h2>Adoption conversations</h2><div id="threadList" class="empty">Loading conversations…</div></section><section class="panel chat"><header class="chat-head"><button class="mobile-back" id="back" aria-label="Back to conversations">‹</button><span class="avatar" id="chatAvatar">🐾</span><div><b id="chatName">Choose a conversation</b><small id="chatPet">Messages will appear here</small></div><span class="status" id="refreshStatus">Live inbox</span></header><div id="chatLog" class="log"><p class="empty">Select a conversation to reply.</p></div><form id="sendForm" class="send"><input id="messageInput" maxlength="2000" placeholder="Write a reply…" autocomplete="off" disabled><button disabled id="sendButton">Send</button></form></section></div></main><script>
const csrf=document.querySelector('[name="csrf-token"]').content;let threads=[],selected='';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const time=s=>{const d=new Date(s);return Number.isNaN(d.getTime())?'':d.toLocaleString([], {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})};
async function api(data){const r=await fetch('api/messages.php',{method:data?'POST':'GET',credentials:'same-origin',headers:{Accept:'application/json',...(data?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{})},body:data?JSON.stringify(data):undefined});const x=await r.json();if(!r.ok||!x.success)throw Error(x.message||'Could not load messages');return x}
function draw(){const list=document.getElementById('threadList');list.className=threads.length?'':'empty';if(!threads.length){list.textContent='No adoption conversations yet. Interested adopters will appear here.';selected='';drawChat();return}list.innerHTML=threads.map(t=>`<button class="thread ${t.id===selected?'active':''}" data-thread="${esc(t.id)}"><span class="avatar">${esc((t.buyerName||'B').slice(0,1).toUpperCase())}</span><span><b>${esc(t.buyerName)} · ${esc(t.petName)}</b><small>${esc(t.messages?.at(-1)?.text||'New conversation')}</small></span></button>`).join('');list.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>{selected=b.dataset.thread;document.getElementById('inbox').classList.add('chat-open');draw()});drawChat()}
function drawChat(){const t=threads.find(x=>x.id===selected),log=document.getElementById('chatLog'),input=document.getElementById('messageInput'),button=document.getElementById('sendButton');input.disabled=!t;button.disabled=!t;document.getElementById('chatName').textContent=t?t.buyerName:'Choose a conversation';document.getElementById('chatPet').textContent=t?`${t.petName} · ${t.listing?.breed||''} · ${t.listing?.age??''} years · ${t.listing?.sex||''} · Pickup: ${t.listing?.pickupLocation||'confirm with buyer'}`:'Messages will appear here';document.getElementById('chatAvatar').textContent=t?(t.buyerName||'B').slice(0,1).toUpperCase():'🐾';if(!t){log.innerHTML='<p class="empty">Select a conversation to reply.</p>';return}log.innerHTML=(t.messages||[]).map(m=>`<div class="bubble ${m.senderId===<?= json_encode((string) $_SESSION['user']['id']) ?>?'mine':''}">${esc(m.text)}<small>${esc(m.senderName)} · ${esc(time(m.sentAt))}</small></div>`).join('');log.scrollTop=log.scrollHeight}
async function refresh(){try{const result=await api();threads=result.conversations||[];if(!selected&&threads.length)selected=threads[0].id;draw()}catch(e){document.getElementById('refreshStatus').textContent=e.message}}
document.getElementById('sendForm').onsubmit=async e=>{e.preventDefault();const input=document.getElementById('messageInput'),button=document.getElementById('sendButton'),text=input.value.trim();if(!selected||!text)return;button.disabled=true;try{const result=await api({action:'reply',conversationId:selected,message:text});const i=threads.findIndex(t=>t.id===selected);if(i>=0)threads[i]=result.conversation;input.value='';draw()}catch(err){document.getElementById('refreshStatus').textContent=err.message}finally{button.disabled=false}};document.getElementById('back').onclick=()=>document.getElementById('inbox').classList.remove('chat-open');refresh();setInterval(refresh,8000);
</script></body></html>
